    internal static bool TryGet(string language, string key, out string? value)
    {
        if (ByLanguage.TryGetValue(language, out var localized) && localized.TryGetValue(key, out value))
            return true;

        if (CharacterFeatureLocalization.TryGet(language, key, out value))
            return true;

        return English.TryGetValue(key, out value);
    }
